import { lazy, memo, Suspense, useCallback, useMemo } from 'react'

import { useAtom } from 'jotai'
import { useNavigate } from 'react-router-dom'

import CloseIcon from '@mui/icons-material/Close'
import {
  Box,
  Checkbox,
  CircularProgress,
  FormControl,
  FormControlLabel,
  FormLabel,
  Grid,
  IconButton,
  InputLabel,
  MenuItem,
  Radio,
  RadioGroup,
  Select,
  Typography,
} from '@mui/material'

import { useStackedTitle } from '@/hooks/useStackedTitle'
import { useTypedSearchParams } from '@/hooks/useTypedSearchParams'
import { routes } from '@/routes'

import {
  learnConfigAtom,
  passRatioAtom,
  type Language,
  type LearnConfig,
  type QaDirection,
  type QaType,
} from '../atoms'
import { useGithubCardContextNext } from '../hooks/useFlashCardContent'
import { useFlashCardItemSummaries } from '../hooks/useFlashCardItemSummaries'
import type { ContentIdentifier } from '../types'

import ContentNavigationBar from './ContentNavigationBar'
import { useHistogramSliderMetrics } from './HistogramSlider.metrics'

// 히스토그램은 @visx/scale + d3-* 차트 라이브러리를 끌어오므로 lazy 분리한다.
const HistogramSlider = lazy(() => import('./HistogramSlider'))

export type LearnConfigEntryProps = {
  className?: string
  contentId: ContentIdentifier
}

function LearnConfigEntryContent(props: LearnConfigEntryProps) {
  const { className, contentId } = props
  const navigate = useNavigate()
  const [learnConfig, setLearnConfig] = useAtom(learnConfigAtom)
  const [passRatio, setPassRatio] = useAtom(passRatioAtom)

  const {
    shuffle,
    qaDirection,
    qaType,
    hideHint,
    soundOnLearning,
    ttsForQuestion,
    ttsForAnswer,
    ttsLang,
  } = learnConfig

  const { content, contentPrev, contentNext } = useGithubCardContextNext(contentId)

  const flashCardItems = useMemo(() => {
    if (!content?.flashCardItems) return []
    return content.flashCardItems
  }, [content])

  const total = flashCardItems.length

  const itemSummaries = useFlashCardItemSummaries(content ?? null, false)
  const passRatioList = useMemo(() => itemSummaries.map((s) => s.passRatio), [itemSummaries])
  const filteredCount = useMemo(
    () => itemSummaries.filter((s) => s.passRatio <= passRatio).length,
    [itemSummaries, passRatio]
  )

  const { totalHeight: histogramTotalHeight } = useHistogramSliderMetrics()

  const handleConfigChange = useCallback(
    (config: Partial<LearnConfig>) => {
      setLearnConfig((prev) => ({ ...prev, ...config }))
    },
    [setLearnConfig]
  )

  const handleStart = useCallback(() => {
    if (qaType === 'one-from-many') {
      navigate(routes.flashMan.learn.oneFromMany.$(contentId))
    } else {
      navigate(routes.flashMan.learn.shortAnswer.$(contentId))
    }
  }, [qaType, navigate, contentId])

  useStackedTitle(content?.name)

  // const handleClose = useCallback(() => {
  //   navigate(routes.flashMan.cards.$(contentId))
  // }, [navigate, contentId])

  // if (!content || total === 0) {
  //   return (
  //     <Box sx={{ padding: 4, textAlign: 'center' }}>
  //       <Typography variant="body2" color="text.secondary">
  //         학습할 카드가 없습니다.
  //       </Typography>
  //       <Button variant="outlined" onClick={handleClose} sx={{ mt: 2 }}>
  //         돌아가기
  //       </Button>
  //     </Box>
  //   )
  // }

  return (
    <Box
      className={className}
      sx={{
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        padding: 2,
      }}
    >
      {/* Header */}
      <Box sx={{ display: 'flex' }}>
        <Box sx={{ transform: 'translate(-.5rem, -.2rem)' }}>
          <IconButton
            onClick={() => {
              navigate(routes.flashMan.cards.$(contentId))
            }}
          >
            <CloseIcon />
          </IconButton>
        </Box>
        <Box sx={{ flexGrow: 1, mb: 3 }}>
          <Typography variant="h6">{content?.name}</Typography>
          <Typography variant="body2" color="text.secondary">
            총 {filteredCount}/{total}개의 문제
          </Typography>
        </Box>
      </Box>

      {/* Histogram Slider: lazy 로딩 전에도 자리를 예약해 CLS를 막는다. */}
      <Box sx={{ mb: 2, height: histogramTotalHeight }}>
        {passRatioList.length > 0 && (
          <Suspense fallback={null}>
            <HistogramSlider samples={passRatioList} value={passRatio} onChange={setPassRatio} />
          </Suspense>
        )}
      </Box>

      {/* Configuration Form */}
      <Box
        sx={{
          flexGrow: 1,
          display: 'flex',
          flexDirection: 'column',
          gap: 2,
          '& .MuiFormControl-root': {
            width: '100%',
          },
        }}
      >
        <Grid container spacing={2}>
          <Grid size={{ xs: 12 }}>
            <FormControlLabel
              control={
                <Checkbox
                  checked={shuffle}
                  onChange={() => handleConfigChange({ shuffle: !shuffle })}
                />
              }
              label="문제 섞기"
            />
          </Grid>

          <Grid size={{ xs: 12 }}>
            <FormControl component="fieldset">
              <FormLabel component="legend">질문 정답 바꾸기</FormLabel>
              <RadioGroup
                row
                name="qa-direction"
                value={qaDirection}
                onChange={(e) => handleConfigChange({ qaDirection: e.target.value as QaDirection })}
              >
                <FormControlLabel value="forward" control={<Radio />} label="문제 -> 답" />
                <FormControlLabel value="reverse" control={<Radio />} label="답 -> 문제" />
              </RadioGroup>
            </FormControl>
          </Grid>

          <Grid size={{ xs: 12 }}>
            <FormControl component="fieldset">
              <FormLabel component="legend">문제 유형</FormLabel>
              <RadioGroup
                row
                name="qa-type"
                value={qaType}
                onChange={(e) => handleConfigChange({ qaType: e.target.value as QaType })}
              >
                <FormControlLabel value="one-from-many" control={<Radio />} label="고르기" />
                <FormControlLabel value="short-answer" control={<Radio />} label="입력하기" />
              </RadioGroup>
            </FormControl>
          </Grid>

          <Grid size={{ xs: 12 }}>
            <FormControlLabel
              control={
                <Checkbox
                  checked={hideHint}
                  onChange={(e) => handleConfigChange({ hideHint: e.target.checked })}
                />
              }
              label="힌트 가리기"
            />
          </Grid>

          <Grid size={{ xs: 12 }}>
            <FormControlLabel
              control={
                <Checkbox
                  checked={soundOnLearning}
                  onChange={(e) => handleConfigChange({ soundOnLearning: e.target.checked })}
                />
              }
              label="효과음"
            />
          </Grid>

          <Grid size={{ xs: 12 }}>
            <FormControlLabel
              control={
                <Checkbox
                  checked={ttsForQuestion}
                  onChange={(e) => handleConfigChange({ ttsForQuestion: e.target.checked })}
                />
              }
              label="문제 말하기"
            />
          </Grid>

          <Grid size={{ xs: 12 }}>
            <FormControlLabel
              control={
                <Checkbox
                  checked={ttsForAnswer}
                  onChange={(e) => handleConfigChange({ ttsForAnswer: e.target.checked })}
                />
              }
              label="정답 말하기"
            />
          </Grid>

          <Grid size={{ xs: 12 }}>
            <FormControl fullWidth>
              <InputLabel id="tts-lang-label">TTS 언어</InputLabel>
              <Select
                labelId="tts-lang-label"
                value={ttsLang}
                label="TTS 언어"
                onChange={(e) => handleConfigChange({ ttsLang: e.target.value as Language })}
              >
                <MenuItem value="ko-KR">한국어</MenuItem>
                <MenuItem value="en-US">영어</MenuItem>
                <MenuItem value="ja-JP">일본어</MenuItem>
              </Select>
            </FormControl>
          </Grid>
        </Grid>
      </Box>

      {/* Action Buttons */}
      <ContentNavigationBar
        contentId={contentId}
        content={content}
        contentPrev={contentPrev}
        contentNext={contentNext}
        onStartClick={0 < flashCardItems.length ? handleStart : undefined}
      />
    </Box>
  )
}

function LearnConfigEntry() {
  const { queryParams } = useTypedSearchParams(routes.flashMan.learn.$config)
  const { owner, repo, path } = queryParams
  return (
    <Suspense
      fallback={
        <Box
          sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '50vh' }}
        >
          <CircularProgress />
        </Box>
      }
    >
      {owner && repo && path ? (
        <LearnConfigEntryContent contentId={{ owner, repo, path }} />
      ) : (
        <>
          <Box>Invalid parameters</Box>
        </>
      )}
    </Suspense>
  )
}

export default memo(LearnConfigEntry)
