import useMediaQuery from '@mui/material/useMediaQuery'

/** svg 히스토그램 높이(px). */
export const HISTOGRAM_HEIGHT = 80

/** MUI Slider 기본 높이(px): height 4 + padding 13*2. */
const SLIDER_HEIGHT_FINE = 30

/** MUI Slider의 coarse pointer(터치) 높이(px): height 4 + padding 20*2. */
const SLIDER_HEIGHT_COARSE = 44

/**
 * HistogramSlider는 lazy 로딩되므로, 로딩 전/후 높이가 다르면 아래 폼 전체가
 * 밀리면서 CLS가 발생한다. 자리 예약(placeholder)과 실제 렌더가 같은 값을 쓰도록
 * 높이 계산을 이 훅으로 모은다.
 */
export function useHistogramSliderMetrics() {
  const coarsePointer = useMediaQuery('(pointer: coarse)')
  const sliderHeight = coarsePointer ? SLIDER_HEIGHT_COARSE : SLIDER_HEIGHT_FINE
  return {
    histogramHeight: HISTOGRAM_HEIGHT,
    sliderHeight,
    totalHeight: HISTOGRAM_HEIGHT + sliderHeight,
  }
}
